<script>
document.addEventListener('DOMContentLoaded',function(){const data=<?php echo wp_json_encode($rows,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>,modal=document.getElementById('outage-modal');function openDetail(i){const r=data[i];if(!r)return;document.getElementById('modal-title').textContent=r.region;document.getElementById('modal-area').textContent=r.area;document.getElementById('modal-date').textContent=r.date;document.getElementById('modal-time').textContent=r.from+' تا '+r.to;document.getElementById('modal-duration').textContent=r.duration;document.getElementById('modal-type').textContent=r.type;document.getElementById('modal-code').textContent=r.code;document.getElementById('modal-reason').textContent=r.reason;document.getElementById('modal-description').textContent=r.details;document.getElementById('modal-streets').textContent=r.streets;document.getElementById('modal-notice').textContent='⚠️ '+r.notice;modal.classList.add('show');modal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}function closeDetail(){modal.classList.remove('show');modal.setAttribute('aria-hidden','true');document.body.style.overflow=''}document.querySelectorAll('.details-btn').forEach(b=>b.addEventListener('click',function(e){e.preventDefault();openDetail(Number(this.dataset.outage))}));document.getElementById('modal-close').addEventListener('click',closeDetail);document.getElementById('modal-ok').addEventListener('click',closeDetail);modal.addEventListener('click',e=>{if(e.target===modal)closeDetail()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDetail()});const search=document.getElementById('outage-search'),date=document.getElementById('outage-date'),type=document.getElementById('outage-type'),btn=document.getElementById('outage-filter'),cards=[...document.querySelectorAll('.schedule-card')],empty=document.getElementById('no-results'),count=document.getElementById('count-total');function filter(){const q=(search.value||'').trim().toLowerCase(),d=date.value,t=type.value;let n=0;cards.forEach(c=>{const okQ=!q||c.dataset.search.toLowerCase().includes(q),okD=d==='all'||c.dataset.date===d,okT=t==='all'||c.dataset.type===t,cok=okQ&&okD&&okT;c.style.display=cok?'block':'none';if(cok)n++});empty.style.display=n?'none':'block';count.textContent=n}btn.addEventListener('click',filter);search.addEventListener('input',filter);date.addEventListener('change',filter);type.addEventListener('change',filter)});
</script>
